void EntityWeaponAttack(Entity* self) {
    Primitive* prim;
    u16 baseX, baseY;
    u16 offset;

    switch (self->step) {
    case 0:
        self->posX.i.hi = PLAYER.posX.i.hi;
        self->posY.i.hi = PLAYER.posY.i.hi;
        self->primIndex = g_api.AllocPrimitives(PRIM_GT4, 1);
        if (self->primIndex == -1) {
            DestroyEntity(self);
            return;
        }

        SetSpriteBank1(g_Animset);
        self->animSet = ANIMSET_OVL(0x10);
        self->palette = PAL_UNK_110;
        self->unk5A = 0x64;
        if (g_HandId != 0) {
            self->animSet += 2;
            self->palette += 0x18;
            self->unk5A += 2;
        }

        prim = &g_PrimBuf[self->primIndex];
        prim->tpage = 0x1A;
        prim->clut = PAL_UNK_1B0;
        prim->u2 = prim->u0 = 0x40;
        prim->v0 = prim->v1 = 0xC0;
        prim->u3 = prim->u1 = 0x7F;
        prim->v2 = prim->v3 = 0xFF;
        prim->r3 = prim->g3 = prim->b3 = 0;
        prim->r2 = prim->g2 = prim->b2 = 0;
        prim->r1 = prim->g1 = prim->b1 = 0;
        prim->r0 = prim->g0 = prim->b0 = 0;

        prim->priority = PLAYER.zPriority + 4;
        prim->drawMode = DRAW_TPAGE2 | DRAW_TPAGE | DRAW_COLORS | DRAW_TRANSP;

        self->ext.weapon.unk7E = 0x7F;
        self->facingLeft = 0;
        self->flags =
            FLAG_KEEP_ALIVE_OFFCAMERA | FLAG_HAS_PRIMS | FLAG_POS_PLAYER_LOCKED;
        self->zPriority = PLAYER.zPriority + 4;
        self->drawFlags = ENTITY_SCALEX | ENTITY_SCALEY | ENTITY_ROTATE;
        self->scaleX = self->scaleY = 0x100;

        g_api.PlaySfx(SFX_WEAPON_APPEAR);
        g_api.PlaySfx(SFX_EXPLODE_A);
        g_Player.timers[12] = 4;
        self->step++;
        break;
    case 1:
        self->posX.i.hi = PLAYER.posX.i.hi;
        self->posY.i.hi = PLAYER.posY.i.hi;
        if (self->ext.weapon.unk7E > 8) {
            self->ext.weapon.unk7E -= 16;
        } else {
            g_PrimBuf[self->primIndex].drawMode = DRAW_HIDE;
            self->anim = D_89000_8017A52C;
            self->ext.weapon.unk7E = 0;
            self->flags |= FLAG_UNK_100000;
            SetWeaponProperties(self, 0);
            self->step++;
        }
        break;
    case 2:
        self->hitboxState = 0;
        self->posX.i.hi = PLAYER.posX.i.hi;
        self->posY.i.hi = PLAYER.posY.i.hi;
        if (self->poseTimer == 1 && self->pose == 3) {
            self->blendMode = BLEND_TRANSP | BLEND_ADD;
        }
        if (self->pose == 5) {
            self->opacity = 0x80;
            self->flags &= ~FLAG_POS_PLAYER_LOCKED;
            self->drawFlags |= ENTITY_OPACITY;
            self->step++;
        }
        break;
    case 3:
        self->scaleX += 0x10;
        self->scaleY = self->scaleX;
        self->rotate += ROT(5.625);
        if (self->opacity >= 5) {
            self->opacity += 0xFE;
        }
        if (self->poseTimer < 0) {
            DestroyEntity(self);
            return;
        }
        break;
    }

    prim = &g_PrimBuf[self->primIndex];
    offset = self->ext.weapon.unk7E;
    baseX = self->posX.i.hi;
    baseY = self->posY.i.hi;
    prim->x0 = prim->x2 = baseX - offset;
    prim->x1 = prim->x3 = baseX + offset;
    prim->y0 = prim->y1 = baseY - offset;
    prim->y2 = prim->y3 = baseY + offset;
    prim->b3 += 0x10;
    if (prim->b3 >= 0x80) {
        prim->b3 = 0x80;
    }
    prim->r0 = prim->g0 = prim->b0 = prim->r1 = prim->g1 = prim->b1 = prim->r2 =
        prim->g2 = prim->b2 = prim->r3 = prim->g3 = prim->b3;
}

